#include "../include/sleela_vm_management.h"
int sleela_vm_memory_plan_validate(const sleela_vm_memory_plan_t *p){if(!p)return-1;if(!p->heap_limit||!p->stack_limit||!p->object_limit)return-2;if(!p->page_size)return-3;if(p->reserved_limit&&p->reserved_limit<p->heap_limit)return-4;if(p->checkpoint_code&&!p->integrity_code)return-5;if(p->migration_code&&!p->checkpoint_code)return-6;if(p->encryption_code&&!p->integrity_code)return-7;return 0;}
int sleela_vm_memory_feature_enabled(const sleela_vm_memory_plan_t *p,uint32_t f){if(!p||f>=8)return 0;switch(f){case 0:return p->guard_code!=0;case 1:return p->quarantine_code!=0;case 2:return p->scrub_code!=0;case 3:return p->checkpoint_code!=0;case 4:return p->migration_code!=0;case 5:return p->encryption_code!=0;case 6:return p->integrity_code!=0;default:return p->gc_code!=0;}}
int sleela_vm_security_plan_validate(const sleela_vm_security_plan_t *p){if(!p)return-1;if(!p->policy_code||!p->capability_code||!p->isolation_code)return-2;if(p->replay_code&&!p->crypto_code)return-3;if(p->certificate_code&&!p->crypto_code)return-4;if(p->attestation_code&&!p->certificate_code)return-5;if(p->delegation_code&&!p->audit_code)return-6;if(p->provenance_code&&!p->audit_code)return-7;return 0;}
int sleela_vm_security_feature_enabled(const sleela_vm_security_plan_t *p,uint32_t f){if(!p||f>=8)return 0;switch(f){case 0:return p->crypto_code!=0;case 1:return p->certificate_code!=0;case 2:return p->resolver_code!=0;case 3:return p->replay_code!=0;case 4:return p->attestation_code!=0;case 5:return p->delegation_code!=0;case 6:return p->provenance_code!=0;default:return p->recovery_code!=0;}}